"""UCHIHA Store + Platform — Core Minimal Phase 12 with automatic Binance deposits and backups.
أمر التشغيل: python uchiha.py
فحص الكود: python uchiha.py --check-code
إنشاء نسخة يدويًا: python uchiha.py --backup-now
فحص القواعد: python uchiha.py --check-databases
"""
from __future__ import annotations
import os

# يمنع تعارض ملف التشغيل القديم platform.py مع مكتبة Python القياسية platform.
# عند أول تشغيل فقط، يُعطّل الملف القديم تلقائيًا بدل حذفه.
if __name__ == "__main__":
    _root = os.path.dirname(os.path.abspath(__file__))
    _legacy = os.path.join(_root, "platform.py")
    if os.path.isfile(_legacy):
        _disabled = os.path.join(_root, ".old_platform.py")
        try:
            if os.path.exists(_disabled):
                os.remove(_disabled)
            os.replace(_legacy, _disabled)
            print("✅ تم تعطيل ملف platform.py القديم لتجنب تعارض مكتبة Python.", flush=True)
        except OSError as exc:
            raise RuntimeError(
                "احذف أو غيّر اسم platform.py القديم قبل التشغيل؛ فهو يتعارض مع مكتبة Python."
            ) from exc

