def _env_flag(name: str, default: bool) -> bool:
    raw = os.getenv(name, "1" if default else "0").strip().lower()
    return raw in {"1", "true", "yes", "on"}


def _telegram_backup_export_enabled() -> bool:
    """Require a new explicit master switch before any database leaves Railway."""
    return _env_flag("ALLOW_DATABASE_EXPORT_TO_TELEGRAM", False)


def backup_keep_count() -> int:
    try:
        return max(1, min(10, int(os.getenv("BACKUP_KEEP", "3"))))
    except Exception:
        return 3


def _backup_interval_seconds() -> int:
    try:
        hours = float(os.getenv("BACKUP_INTERVAL_HOURS", "12"))
    except Exception:
        hours = 12.0
    return max(3600, int(hours * 3600))


def _sqlite_path_from_url(url: str) -> Path | None:
    value = (url or "").strip()
    for prefix in ("sqlite+aiosqlite:///", "sqlite:///"):
        if value.startswith(prefix):
            raw = value[len(prefix):]
            return Path(raw or "uchiha_platform.db")
    return None


def _database_entries() -> list[tuple[str, Path, tuple[str, ...], bool]]:
    entries: list[tuple[str, Path, tuple[str, ...], bool]] = []
    store = Path(os.getenv("DB_PATH", "store.db").strip() or "store.db")
    platform_db = _sqlite_path_from_url(
        os.getenv("DATABASE_URL", "sqlite+aiosqlite:///./uchiha_platform.db")
    ) or Path("uchiha_platform.db")
    entries.append(("store", store, ("orders", "users"), True))
    entries.append(("platform", platform_db, ("stores", "merchants"), True))
    merchant_dir = Path(os.getenv("MERCHANT_DATA_DIR", "merchant_data").strip() or "merchant_data")
    if merchant_dir.exists():
        for path in sorted(merchant_dir.glob("*.db")):
            entries.append((f"merchant:{path.stem}", path, (), False))
    seen: set[str] = set()
    result: list[tuple[str, Path, tuple[str, ...], bool]] = []
    for label, path, expected, critical in entries:
        key = str(path.expanduser().absolute())
        if key in seen:
            continue
        seen.add(key)
        result.append((label, path, expected, critical))
    return result


def _inspect_sqlite(path: Path, expected: tuple[str, ...] = (), *, full: bool = False) -> dict[str, object]:
    result: dict[str, object] = {
        "path": str(path), "exists": path.exists(), "size": 0, "status": "missing",
        "integrity": "not_checked", "tables": [], "missing_tables": list(expected),
    }
    if not path.exists():
        return result
    try:
        result["size"] = path.stat().st_size
    except OSError as exc:
        result["status"] = "unreadable"
        result["error"] = str(exc)
        return result
    if int(result["size"]) == 0:
        result["status"] = "empty"
        return result
    connection = None
    try:
        uri = f"file:{path.expanduser().absolute()}?mode=ro"
        connection = sqlite3.connect(uri, uri=True, timeout=5)
        pragma = "PRAGMA integrity_check" if full else "PRAGMA quick_check"
        row = connection.execute(pragma).fetchone()
        integrity = str(row[0] if row else "unknown")
        tables = [
            str(item[0]) for item in connection.execute(
                "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
            ).fetchall()
        ]
        missing = [name for name in expected if name not in tables]
        result.update(integrity=integrity, tables=tables, missing_tables=missing)
        if integrity.lower() != "ok":
            result["status"] = "corrupt"
        elif not tables:
            result["status"] = "empty_schema"
        elif missing:
            result["status"] = "wrong_schema"
        else:
            result["status"] = "ok"
    except Exception as exc:
        result["status"] = "error"
        result["error"] = f"{exc.__class__.__name__}: {exc}"
    finally:
        if connection is not None:
            connection.close()
    return result


def database_health() -> list[dict[str, object]]:
    records: list[dict[str, object]] = []
    for label, path, expected, critical in _database_entries():
        item = _inspect_sqlite(path, expected, full=True)
        item["label"] = label
        item["critical"] = critical
        records.append(item)
    return records


def _human_bytes(value: int) -> str:
    size = float(max(0, int(value)))
    for unit in ("B", "KB", "MB", "GB"):
        if size < 1024 or unit == "GB":
            return f"{size:.1f} {unit}"
        size /= 1024
    return f"{size:.1f} GB"


def database_health_text(full: bool = False) -> str:
    lines: list[str] = []
    entries = _database_entries()
    for label, path, expected, critical in entries:
        item = _inspect_sqlite(path, expected, full=full)
        status = str(item.get("status"))
        icon = "✅" if status == "ok" else ("⚪" if status in {"missing", "empty"} else "❌")
        lines.append(f"{icon} {label}: {status} — {_human_bytes(int(item.get('size', 0)))}")
        missing = item.get("missing_tables") or []
        if missing and status not in {"missing", "empty"}:
            lines.append("   جداول ناقصة: " + ", ".join(map(str, missing)))
        if item.get("error"):
            lines.append("   " + str(item["error"])[:180])
    return "\n".join(lines) if lines else "لا توجد قواعد بيانات مسجلة."


def _preflight_database_guard() -> None:
    problems: list[str] = []
    for label, path, expected, critical in _database_entries():
        item = _inspect_sqlite(path, expected, full=False)
        status = str(item.get("status"))
        if critical and status not in {"ok", "missing", "empty"}:
            problems.append(f"{label}: {status}")
        elif not critical and status not in {"ok", "missing", "empty"}:
            logging.getLogger(__name__).warning("قاعدة متجر تاجر غير سليمة ولن تُضمَّن في النسخة: %s (%s)", path, status)
    if problems:
        raise RuntimeError(
            "تم إيقاف التشغيل لحماية البيانات. توجد قاعدة غير سليمة: " + "; ".join(problems)
            + ". افحصها من لوحة الاستضافة قبل المتابعة."
        )


def _copy_sqlite_consistent(source: Path, destination: Path) -> None:
    destination.parent.mkdir(parents=True, exist_ok=True)
    src = sqlite3.connect(f"file:{source.expanduser().absolute()}?mode=ro", uri=True, timeout=10)
    dst = sqlite3.connect(destination)
    try:
        src.backup(dst, pages=256, sleep=0.01)
        row = dst.execute("PRAGMA integrity_check").fetchone()
        if not row or str(row[0]).lower() != "ok":
            raise RuntimeError(f"فشل فحص النسخة: {source}")
    finally:
        dst.close()
        src.close()


def _backup_dir() -> Path:
    return Path(os.getenv("BACKUP_DIR", ".backups").strip() or ".backups")


def list_backup_paths() -> list[Path]:
    directory = _backup_dir()
    if not directory.exists():
        return []
    return sorted(directory.glob("uchiha_backup_*.zip"), key=lambda p: p.stat().st_mtime, reverse=True)


def latest_backup_path() -> Path | None:
    items = list_backup_paths()
    return items[0] if items else None


def _rotate_backups() -> None:
    for old in list_backup_paths()[backup_keep_count():]:
        try:
            old.unlink()
        except OSError:
            logging.getLogger(__name__).exception("تعذر حذف نسخة قديمة: %s", old)


def _backup_fingerprint(archive: Path) -> str:
    try:
        with zipfile.ZipFile(archive) as zf:
            data = json.loads(zf.read("manifest.json").decode("utf-8"))
        return str(data.get("fingerprint", ""))
    except Exception:
        return hashlib.sha256(archive.read_bytes()).hexdigest()


def create_backup_archive(reason: str = "manual") -> Path | None:
    directory = _backup_dir()
    directory.mkdir(parents=True, exist_ok=True)
    stamp = datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S_%f")
    safe_reason = "".join(ch for ch in reason.lower() if ch.isalnum() or ch in {"-", "_"})[:24] or "backup"
    archive = directory / f"uchiha_backup_{stamp}_{safe_reason}.zip"
    temp_root = Path(tempfile.mkdtemp(prefix=".backup_tmp_", dir=directory))
    files: list[dict[str, object]] = []
    digests: list[str] = []
    try:
        for label, source, expected, _critical in _database_entries():
            inspected = _inspect_sqlite(source, expected, full=False)
            if inspected.get("status") != "ok":
                continue
            if label == "store":
                relative = Path("databases/store.db")
            elif label == "platform":
                relative = Path("databases/uchiha_platform.db")
            else:
                relative = Path("merchant_data") / source.name
            copied = temp_root / relative
            _copy_sqlite_consistent(source, copied)
            digest = hashlib.sha256(copied.read_bytes()).hexdigest()
            digests.append(f"{relative}:{digest}")
            files.append({
                "label": label,
                "archive_path": relative.as_posix(),
                "source": str(source),
                "size": copied.stat().st_size,
                "sha256": digest,
            })
        if not files:
            return None
        fingerprint = hashlib.sha256("\n".join(sorted(digests)).encode("utf-8")).hexdigest()
        manifest = {
            "created_at": datetime.now(timezone.utc).isoformat(),
            "reason": reason,
            "fingerprint": fingerprint,
            "files": files,
            "restore_note": "أوقف السيرفر قبل استعادة أي قاعدة بيانات.",
        }
        (temp_root / "manifest.json").write_text(
            json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8"
        )
        with zipfile.ZipFile(archive, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=6) as zf:
            for item in sorted(temp_root.rglob("*")):
                if item.is_file():
                    zf.write(item, item.relative_to(temp_root).as_posix())
        status_file = directory / "backup_status.json"
        status_file.write_text(
            json.dumps({"latest": archive.name, **manifest}, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        _rotate_backups()
        logging.getLogger(__name__).info("تم إنشاء نسخة احتياطية: %s", archive)
        return archive
    finally:
        shutil.rmtree(temp_root, ignore_errors=True)


async def send_backup_to_owner(path: Path, *, force: bool = False) -> bool:
    token = os.getenv("PLATFORM_BOT_TOKEN", "").strip()
    raw_owner = os.getenv("PLATFORM_OWNER_ID", os.getenv("ADMIN_ID", "0")).strip()
    if not token or not raw_owner.isdigit() or int(raw_owner) <= 0:
        logging.getLogger(__name__).warning("تعذر إرسال النسخة: PLATFORM_BOT_TOKEN أو PLATFORM_OWNER_ID ناقص.")
        return False
    directory = _backup_dir()
    fingerprint = _backup_fingerprint(path)
    marker = directory / ".last_telegram_fingerprint"
    if not force and marker.exists() and marker.read_text(encoding="utf-8").strip() == fingerprint:
        return False
    from aiogram import Bot
    from aiogram.types import FSInputFile
    bot = Bot(token=token)
    try:
        await bot.send_document(
            chat_id=int(raw_owner),
            document=FSInputFile(path),
            caption=(
                "💾 نسخة UCHIHA الاحتياطية\n"
                f"الملف: {path.name}\n"
                "تحتوي قواعد البيانات فقط، ولا تحتوي ملف .env أو التوكنات."
            ),
        )
    finally:
        await bot.session.close()
    marker.write_text(fingerprint, encoding="utf-8")
    return True


async def _automatic_backup_worker() -> None:
    logger = logging.getLogger(__name__)
    while True:
        await asyncio.sleep(_backup_interval_seconds())
        try:
            path = await asyncio.to_thread(create_backup_archive, "scheduled")
            if path and _telegram_backup_export_enabled() and _env_flag("BACKUP_SEND_TO_TELEGRAM", True):
                await send_backup_to_owner(path, force=False)
        except asyncio.CancelledError:
            raise
        except Exception:
            logger.exception("فشل النسخ الاحتياطي الدوري")

def _sources():
    try:data=json.loads(zlib.decompress(base64.b85decode(_PAYLOAD.encode('ascii'))).decode('utf-8'))
    except Exception as exc:raise RuntimeError('تعذر قراءة كود منصة UCHIHA المدمج.') from exc
    for name,expected in _HASHES.items():
        source=data.get(name)
        if not isinstance(source,str):raise RuntimeError(f'الكود المدمج ناقص: {name}')
        if hashlib.sha256(source.encode()).hexdigest()!=expected:raise RuntimeError(f'فشل فحص سلامة الكود: {name}')
    return data
class _Loader(importlib.abc.Loader):
    def __init__(self,name,source):self.name=name;self.source=source
    def create_module(self,spec):return None
    def exec_module(self,module):
        filename=f'<UCHIHA_PLATFORM:{self.name}>';module.__file__=filename;module.__package__='';exec(compile(self.source,filename,'exec'),module.__dict__)
class _Finder(importlib.abc.MetaPathFinder):
    def __init__(self,data):self.data=data
    def find_spec(self,fullname,path=None,target=None):
        source=self.data.get(fullname)
        if source is None:return None
        return importlib.util.spec_from_loader(fullname,_Loader(fullname,source),origin=f'embedded://{fullname}')
def _install():
    data=_sources();sys.meta_path.insert(0,_Finder(data));return data
def _check():
    data=_sources()
    for name,source in data.items():compile(source,f'<UCHIHA_PLATFORM:{name}>','exec')
    compile(open('bot.py',encoding='utf-8').read(),'bot.py','exec');compile(open('api_js4card.py',encoding='utf-8').read(),'api_js4card.py','exec');compile(open('storefront_api.py',encoding='utf-8').read(),'storefront_api.py','exec')
    print(f'✅ فحص ناجح: 4 ملفات أكواد، و{len(data)} أجزاء منصة مدمجة داخل uchiha.py')
    print('✅ لوحة متجر التاجر مطابقة في أقسامها الأساسية للوحة UCHIHA STORE مع أدوات التاجر الخاصة.')
async def _platform_bot_only(platform_app):
    settings=platform_app.get_settings();bot,dispatcher=await platform_app.build_dispatcher(settings)
    try:await dispatcher.start_polling(bot,allowed_updates=dispatcher.resolve_used_update_types())
    finally:await bot.session.close()
async def _platform_mode(platform_app):
    enabled=_env_flag('PLATFORM_API_ENABLED',False)
    if enabled:logging.getLogger(__name__).warning('واجهة API العامة مفعلة على المنفذ المحدد.');await platform_app.run_platform()
    else:await _platform_bot_only(platform_app)
async def _run():
    logging.basicConfig(
        level=getattr(logging,os.getenv('LOG_LEVEL','INFO').upper(),logging.INFO),
        format='%(asctime)s | %(levelname)s | %(name)s | %(message)s',
    )
    _preflight_database_guard()
    # نسخة قبل أي تهيئة/ترحيل عندما تكون القواعد الحالية سليمة.
    prestart_backup=await asyncio.to_thread(create_backup_archive,'prestart')
    if not os.getenv('API_PORT','').strip():os.environ['API_PORT']=os.getenv('PORT','8080').strip() or '8080'
    _install();import bot as store_app;import platform_app,merchant_runtime,bot_builder,platform_control,supplier_service,partner_api;import storefront_api
    storefront_api.install_storefront_routes(platform_app.app)
    required={'BOT_TOKEN':os.getenv('BOT_TOKEN','').strip(),'PLATFORM_BOT_TOKEN':os.getenv('PLATFORM_BOT_TOKEN','').strip()};missing=[k for k,v in required.items() if not v]
    if missing:raise RuntimeError('متغيرات ناقصة داخل .env: '+', '.join(missing))
    # أنشئ جداول المتجر أولًا قبل تشغيل أي عامل قد يقرأ الطلبات.
    await store_app.init_db()
    await platform_app.init_database()
    async with platform_app.SessionFactory() as session:await platform_app.ensure_default_plans(session);await platform_control.ensure_defaults(session)
    # بعد التهيئة يجب أن تكون القواعد الأساسية سليمة. القاعدة الفارغة الجديدة تصبح صالحة هنا.
    for label,path,expected,critical in _database_entries():
        if not critical:continue
        state=await asyncio.to_thread(_inspect_sqlite,path,expected,full=True)
        if state.get('status')!='ok':raise RuntimeError(f'فشل فحص قاعدة {label} بعد التهيئة: {state.get("status")}')
    # نسخة جديدة بعد اكتمال التهيئة؛ مهمة خصوصًا عندما كانت store.db مفقودة أو فارغة.
    active_backup=await asyncio.to_thread(create_backup_archive,'startup')
    if active_backup is None:active_backup=prestart_backup
    if active_backup and _telegram_backup_export_enabled() and _env_flag('BACKUP_SEND_ON_STARTUP',True) and _env_flag('BACKUP_SEND_TO_TELEGRAM',True):
        try:await send_backup_to_owner(active_backup,force=False)
        except Exception:logging.getLogger(__name__).exception('تعذر إرسال نسخة بدء التشغيل')
    tasks={'UCHIHA STORE':asyncio.create_task(store_app.main()),'UCHIHA PLATFORM':asyncio.create_task(_platform_mode(platform_app)),'AUTOMATIC BACKUPS':asyncio.create_task(_automatic_backup_worker())}
    if _env_flag('STOREFRONT_API_ENABLED',True) and not _env_flag('PLATFORM_API_ENABLED',False):tasks['STOREFRONT API']=asyncio.create_task(storefront_api.run_storefront_api())
    if os.getenv('MERCHANT_BOTS_ENABLED','1').strip().lower() in {'1','true','yes','on'}:tasks['MERCHANT BOTS']=asyncio.create_task(merchant_runtime.run_merchant_bots())
    else:logging.getLogger(__name__).warning('تشغيل بوتات التجار مغلق من .env')
    if os.getenv('SUPPLIER_WORKER_ENABLED','1').strip().lower() in {'1','true','yes','on'}:tasks['SUPPLIER WORKER']=asyncio.create_task(supplier_service.run_supplier_worker())
    else:logging.getLogger(__name__).warning('عامل متابعة طلبات المورد مغلق من .env')
    if os.getenv('PARTNER_WEBHOOK_WORKER_ENABLED','1').strip().lower() in {'1','true','yes','on'}:tasks['PARTNER WEBHOOK WORKER']=asyncio.create_task(partner_api.run_partner_webhook_worker())
    else:logging.getLogger(__name__).warning('عامل Webhook للشركاء مغلق من .env')
    if os.getenv('MANAGED_BOTS_ENABLED','0').strip().lower() in {'1','true','yes','on'}:tasks['MANAGED BOT BRIDGE']=asyncio.create_task(bot_builder.run_managed_bot_bridge())
    else:logging.getLogger(__name__).warning('إنشاء البوتات المُدارة مغلق حتى اكتمال إعداد تيليجرام')
    try:
        done,pending=await asyncio.wait(tasks.values(),return_when=asyncio.FIRST_EXCEPTION);failure=None
        for task in done:
            try:task.result()
            except asyncio.CancelledError:pass
            except BaseException as exc:failure=exc;break
        for task in pending:task.cancel()
        await asyncio.gather(*pending,return_exceptions=True)
        if failure is not None:raise failure
    finally:
        for task in tasks.values():
            if not task.done():task.cancel()
        await asyncio.gather(*tasks.values(),return_exceptions=True)

def main():
    if sys.version_info<_MIN_PYTHON:raise RuntimeError('اختر Python 3.12 أو أحدث.')
    parser=argparse.ArgumentParser(description='UCHIHA Core Minimal Phase 11.1')
    parser.add_argument('--check-code',action='store_true')
    parser.add_argument('--backup-now',action='store_true')
    parser.add_argument('--check-databases',action='store_true')
    args=parser.parse_args()
    if args.check_code:_check();return
    if args.check_databases:print(database_health_text(full=True));return
    if args.backup_now:
        path=create_backup_archive('manual_cli')
        print(f'✅ {path}' if path else '⚠️ لا توجد قواعد سليمة لإنشاء نسخة.')
        return
    try:asyncio.run(_run())
    except KeyboardInterrupt:pass
if __name__=='__main__':main()
